"""Independent agriculture reconstruction and sector/finance conservation."""
from pathlib import Path
import json,hashlib
import pandas as pd,numpy as np,pyarrow.parquet as pq
O=Path(__file__).resolve().parent;R=O.parent;checks=[]
def ck(name,cond,**ev):
 checks.append(dict(test=name,passed=bool(cond),**ev))
 if not cond:raise AssertionError(checks[-1])
A=R/'agriculture';meta=json.loads((A/'audit.json').read_text());source=Path(meta['inputs'][0]['path']);ck('raw_agriculture_sha',hashlib.sha256(source.read_bytes()).hexdigest()==meta['inputs'][0]['sha256'])
