for b in pq.ParquetFile(source).iter_batches(batch_size=100000,columns=['year','indicator_code','mun_level','kategor','kultur','oktmo','indicator_value']):
 d=b.to_pandas();d=d[d.year.eq(2021)&d.indicator_code.eq('Y48007018')&d.mun_level.eq('Муниципальное образование верхнего уровня')&d.kategor.eq('Хозяйства всех категорий')].copy();d['group']=d.kultur.str.strip().map(names);pieces.append(d[d.group.notna()])
r=pd.concat(pieces);r['oktmo']=r.oktmo.astype('string').str.zfill(8);r=r[~r.duplicated(['oktmo','group'],False)];p=r.pivot(index='oktmo',columns='group',values='indicator_value');groups=['grain','technical','fodder','potato','vegetables','melon'];v=p[groups];knownsum=v.sum(axis=1,min_count=1);over=(knownsum>p.total*1.02+1e-8)|v.lt(0).any(axis=1)|p.total.lt(0);share=v.div(p.total.replace(0,np.nan),axis=0);maxsh=share.max(axis=1);dom=share.fillna(-1).idxmax(axis=1);profile=pd.Series('missing',index=p.index);profile.loc[p.total.eq(0)&~v.gt(0).any(axis=1)&~over]='zero_sown';profile.loc[maxsh.ge(.5)&~over]=dom;profile.loc[v.notna().all(axis=1)&knownsum.div(p.total).ge(.9)&maxsh.lt(.5)&~over]='mixed'
actual=pd.read_csv(A/'municipal_crop_profiles_2021.csv',dtype={'oktmo':str});actual['oktmo']=actual.oktmo.str.zfill(8);actual=actual.set_index('oktmo');ck('source_municipal_profile_ids',set(profile.index)==set(actual.index));ck('all_municipal_profiles_reconstructed_from_raw',np.array_equal(profile.sort_index().to_numpy(),actual.municipal_profile.sort_index().to_numpy()),municipalities=len(profile));ck('all_accepted_profiles_not_overfull',not bool(over[profile.ne('missing')].any()))
panel=pd.read_parquet(R/'data/panel.parquet',columns=['id','municipality_oktmo8_2021']);m=pd.read_parquet(R/'model/nearest_membership.parquet',columns=['id','center_id']);x=m.merge(panel,on='id',validate='one_to_one');x['municipal_profile']=x.municipality_oktmo8_2021.astype('string').str.zfill(8).map(profile);x.loc[x.center_id.eq('UNASSIGNED'),'municipal_profile']='missing';x['valid']=x.municipal_profile.notna()&x.municipal_profile.ne('missing');den=x.groupby('center_id').size();cov=x.groupby('center_id').valid.sum()/den;counts=x[x.valid].groupby(['center_id','municipal_profile']).size().unstack(fill_value=0);shares=counts.div(counts.sum(axis=1),axis=0);dominance=shares.max(axis=1);domzone=shares.idxmax(axis=1);pred=pd.Series('missing',index=den.index);covered=cov.ge(.8);pred.loc[covered]='mosaic';yes=covered&dominance.reindex(den.index).ge(.6);pred.loc[yes]=domzone;main=pd.read_csv(A/'zone_functional_main.csv').set_index('center_id');ck('all_zone_crop_profiles_independently_reconstructed',np.array_equal(pred.sort_index().to_numpy(),main.functional_context.sort_index().to_numpy()));ck('all_zone_crop_coverage_independently_reconstructed',np.allclose(cov.sort_index(),main.coverage.sort_index(),atol=1e-12));ck('unobserved_helper_not_false_crop',main.loc[main.coverage.eq(0),'dominant_profile'].eq('unobserved').all())
fwide=pd.read_csv(A/'functional_weight_sensitivity.csv');valid=fwide['count'].ne('missing')&fwide.population2021.ne('missing')&fwide.center_id.ne('UNASSIGNED');agstats=dict(common_adequately_covered=int(valid.sum()),agreement_count_population2021=float(fwide.loc[valid,'count'].eq(fwide.loc[valid,'population2021']).mean()),ordinary_zone_classes=main.drop(index='UNASSIGNED',errors='ignore').functional_context.value_counts().to_dict())
