ww=w.groupby(['year','center_id','quality']).n_organizations.sum();ff=f[f.max_distance_km.eq(5)].set_index(['year','center_id','quality']).n_organizations;ck('RFSD_anchor_witness_is_subset_of_zone',ww.le(ff.reindex(ww.index)).all());ck('RFSD_core_years_2016_2021',set(f.year)=={2016,2021})
